import type {
  ModelRequest,
  ToolDefinition,
  ToolDispatchStatus,
} from "./index.js";

export interface ModelToolSpec {
  id: ToolDefinition["id"];
  description: ToolDefinition["description"];
  inputSchema: ToolDefinition["inputSchema"];
}

export interface ModelToolCall {
  /**
   * Identifier generated by the provider.
   * Used to correlate the response to this call.
   */
  id: string;

  /**
   * Registered tool identifier, e.g. file.read.
   */
  toolId: string;

  /**
   * Untrusted model-generated arguments.
   */
  arguments: Record<string, unknown>;
}

export type ModelToolTurn =
  | {
      kind: "message";
      text: string;
    }
  | {
      kind: "tool_calls";
      calls: ModelToolCall[];
      text?: string;
    };

export interface ModelToolResult {
  callId: string;
  toolId: string;
  status: ToolDispatchStatus;
  data?: unknown;
  error?: string;
}

export interface ModelToolRequest extends ModelRequest {
  tools: readonly ModelToolSpec[];

  /**
   * Results of previously dispatched tool calls.
   */
  toolResults?: readonly ModelToolResult[];
}

/**
 * Optional capability for providers supporting tool calling.
 *
 * Existing ModelProviderAdapter.complete() remains unchanged.
 */
export interface ToolCallingProviderAdapter {
  readonly id: string;

  completeWithTools(request: ModelToolRequest): Promise<ModelToolTurn>;
}
